//! All native automation crosses this gate. Key-up cleanup is restricted to
//! inputs generated by this process; no keyboard hook or typed text collection.
use super::{GameWindow, Input};
use crate::core::types::{Key, MouseButton, PxPoint, PxRect};
use parking_lot::Mutex;
use std::sync::Arc;

#[derive(Default)]
struct Gate {
    enabled: bool,
    keys: Vec<Key>,
    buttons: Vec<MouseButton>,
}

pub struct GuardedInput {
    window: Arc<dyn GameWindow>,
    inner: Arc<dyn Input>,
    gate: Mutex<Gate>,
}

impl GuardedInput {
    pub fn new(window: Arc<dyn GameWindow>, inner: Arc<dyn Input>) -> Self {
        Self {
            window,
            inner,
            gate: Mutex::new(Gate::default()),
        }
    }
    fn release(&self, gate: &mut Gate) {
        for key in gate.keys.drain(..) {
            self.inner.key(key, false);
        }
        for button in gate.buttons.drain(..) {
            self.inner.button(button, false);
        }
    }
    fn active(&self, gate: &mut Gate) -> Option<PxRect> {
        if gate.enabled {
            if let Some(w) = self.window.find().filter(|w| w.visible && w.is_foreground) {
                return Some(w.client);
            }
        }
        self.release(gate);
        None
    }
    fn inside(p: PxPoint, r: PxRect) -> bool {
        p.x >= r.x
            && p.y >= r.y
            && (p.x as i64) < r.x as i64 + r.w as i64
            && (p.y as i64) < r.y as i64 + r.h as i64
    }
}

impl Input for GuardedInput {
    fn set_enabled(&self, enabled: bool) {
        let mut gate = self.gate.lock();
        gate.enabled = enabled;
        if !enabled {
            self.release(&mut gate);
        }
    }
    fn release_all(&self) {
        self.release(&mut self.gate.lock());
    }
    fn move_to(&self, p: PxPoint) {
        let mut gate = self.gate.lock();
        if self.active(&mut gate).is_some_and(|r| Self::inside(p, r)) {
            self.inner.move_to(p);
        }
    }
    fn button(&self, b: MouseButton, down: bool) {
        let mut gate = self.gate.lock();
        if down {
            let cursor = self.inner.cursor();
            if !self
                .active(&mut gate)
                .is_some_and(|r| Self::inside(cursor, r))
                || !self.window.owns_point(cursor)
            {
                return;
            }
            if !gate.buttons.contains(&b) {
                gate.buttons.push(b);
                self.inner.button(b, true);
            }
        } else if let Some(i) = gate.buttons.iter().position(|v| *v == b) {
            gate.buttons.remove(i);
            self.inner.button(b, false);
        }
    }
    fn key(&self, k: Key, down: bool) {
        let mut gate = self.gate.lock();
        if down {
            if self.active(&mut gate).is_none() {
                return;
            }
            if !gate.keys.contains(&k) {
                gate.keys.push(k);
                self.inner.key(k, true);
            }
        } else if let Some(i) = gate.keys.iter().position(|v| *v == k) {
            gate.keys.remove(i);
            self.inner.key(k, false);
        }
    }
    fn wheel(&self, delta: i32) {
        let mut gate = self.gate.lock();
        let cursor = self.inner.cursor();
        if self
            .active(&mut gate)
            .is_some_and(|r| Self::inside(cursor, r))
            && self.window.owns_point(cursor)
        {
            self.inner.wheel(delta);
        }
    }
    fn type_text(&self, s: &str) {
        // Recheck the foreground window for every character.
        for c in s.chars().take(256) {
            self.key(Key::Char(c), true);
            self.key(Key::Char(c), false);
        }
    }
    fn cursor(&self) -> PxPoint {
        self.inner.cursor()
    }
    fn screen(&self) -> PxRect {
        self.inner.screen()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::core::platform::mock::{InputEvent, MockWindow, RecordingInput};
    use crate::core::types::WindowInfo;
    #[test]
    fn focus_loss_releases_our_inputs_and_blocks_new_input() {
        let w = Arc::new(MockWindow::default());
        *w.info.lock() = Some(WindowInfo {
            client: PxRect {
                x: 0,
                y: 0,
                w: 100,
                h: 100,
            },
            visible: true,
            is_foreground: true,
            dpi: 96,
        });
        let raw = Arc::new(RecordingInput::default());
        let input = GuardedInput::new(w.clone(), raw.clone());
        input.key(Key::Control, true); // disabled until explicitly started
        assert!(raw.events.lock().is_empty());
        input.set_enabled(true);
        input.key(Key::Control, true);
        input.button(MouseButton::Left, true);
        w.info.lock().as_mut().unwrap().is_foreground = false;
        input.key(Key::Char('a'), true);
        input.move_to(PxPoint { x: 20, y: 20 });
        input.key(Key::Char('a'), false); // cannot release a user's unrelated key
        assert_eq!(
            *raw.events.lock(),
            vec![
                InputEvent::Key(Key::Control, true),
                InputEvent::Button(MouseButton::Left, true),
                InputEvent::Key(Key::Control, false),
                InputEvent::Button(MouseButton::Left, false)
            ]
        );
    }
    #[test]
    fn emergency_stop_releases_and_disarms() {
        let w = Arc::new(MockWindow::default());
        *w.info.lock() = Some(WindowInfo {
            client: PxRect {
                x: 0,
                y: 0,
                w: 100,
                h: 100,
            },
            visible: true,
            is_foreground: true,
            dpi: 96,
        });
        let raw = Arc::new(RecordingInput::default());
        let input = GuardedInput::new(w, raw.clone());
        input.set_enabled(true);
        input.key(Key::Control, true);
        input.move_to(PxPoint { x: 100, y: 100 }); // excluded right/bottom edge
        input.set_enabled(false);
        input.key(Key::Char('x'), true);
        assert_eq!(
            *raw.events.lock(),
            vec![
                InputEvent::Key(Key::Control, true),
                InputEvent::Key(Key::Control, false)
            ]
        );
    }
}
